const enchantedMemories=[
 {id:'kiss',title:'Bir öpücük, bin güzel his',note:'Zaman aksın; ben yine sana böyle yaklaşayım.',type:'Birlikte yaşadığımız bir an'},
 {id:'sunshine',title:'Güneşim, yanı başımda',note:'O gün deniz parlıyordu. Benim gözüm yine sendeydi.',type:'Birlikte yaşadığımız bir an'},
 {id:'station',title:'Her kalabalıkta seni bulurum',note:'Dünya ne kadar kalabalık olursa olsun, kalbimin yolu sana çıkıyor.',type:'Birlikte yaşadığımız bir an'},
 {id:'saved-kiss',title:'Bu öpücüğü zamana sakladım',note:'Bir fotoğrafın içine sığan, ömrüme yayılan bir sevgi.',type:'Hareketli fotoğraf'},
 {id:'close-hearts',title:'Kalbime en yakın yer',note:'Sana yaslandığımda, bütün dünya biraz daha yumuşak.',type:'Hareketli fotoğraf'}
];
let memoryObserver=null,memoryMotion=true;
function memoryInvitation(){return `<a class="memory-invite" href="#magic"><span aria-hidden="true">✦</span><div><h2>Bazı anılar, çerçevelerinde bile kıpır kıpır.</h2><p>Büyülü anı odasına gir; bir öpücük, bir gülüş, biraz biz…</p></div><b>Kapıyı arala ↗</b></a>`}
function magic(){return `<section class="magic-room"><div class="magic-stars" aria-hidden="true">✧ · ✦ · ✧</div><div class="page-heading"><span class="eyebrow">Biraz büyü, bir dolu biz</span><h1>Yaşayan <em>anı odası.</em></h1><p>Bazı anlar bittiğinde bile içimizde yaşamaya devam eder.<br>Bizimkiler burada, çerçevelerinde saklı.</p><button class="memory-motion" aria-pressed="false">Hareketleri durdur ✧</button></div><div class="portrait-wall">${enchantedMemories.map((m,i)=>`<article class="living-portrait portrait-${i}"><button class="portrait-frame" data-memory="${m.id}" aria-label="${esc(m.title)} videosunu sesli ve büyük aç"><span class="portrait-corner tl" aria-hidden="true">✦</span><video muted loop playsinline preload="none" poster="assets/memories/${m.id}.jpg" data-memory-loop><source src="assets/memories/${m.id}.mp4" type="video/mp4"></video><span class="portrait-glow" aria-hidden="true"></span><span class="portrait-watch">Dokun, anımıza dön ♡</span><span class="portrait-corner br" aria-hidden="true">✦</span></button><div class="portrait-plaque"><small>${esc(m.type)}</small><h2>${esc(m.title)}</h2><p>${esc(m.note)}</p></div></article>`).join('')}</div><p class="magic-whisper">Bir sihir seçebilseydim,<br>seninle güzel anları biraz daha uzun yaşardım. ♡</p><div class="magic-candles" aria-hidden="true"><i></i><i></i><i></i></div><a class="btn secondary" href="#album">Anı günlüğümüze dön ♡</a></section>`}
function mountMagicalMemories(){if(memoryObserver)memoryObserver.disconnect();const videos=document.querySelectorAll('[data-memory-loop]');if(!videos.length)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;memoryMotion=!reduced;const toggle=document.querySelector('.memory-motion');if(toggle){toggle.setAttribute('aria-pressed',String(!memoryMotion));toggle.textContent=memoryMotion?'Hareketleri durdur ✧':'Anılara hayat ver ✧'}memoryObserver=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting&&memoryMotion)target.play().catch(()=>{});else target.pause()}),{threshold:.25});videos.forEach(v=>memoryObserver.observe(v))}
document.addEventListener('click',e=>{const frame=e.target.closest('[data-memory]');if(frame){const m=enchantedMemories.find(m=>m.id===frame.dataset.memory);if(!m)return;show(`<div class="memory-viewer"><video controls autoplay playsinline poster="assets/memories/${m.id}.jpg"><source src="assets/memories/${m.id}.mp4" type="video/mp4"></video><h2>${esc(m.title)}</h2><p>${esc(m.note)}</p></div>`)}const toggle=e.target.closest('.memory-motion');if(toggle){memoryMotion=!memoryMotion;toggle.setAttribute('aria-pressed',String(!memoryMotion));toggle.textContent=memoryMotion?'Hareketleri durdur ✧':'Anılara hayat ver ✧';document.querySelectorAll('[data-memory-loop]').forEach(v=>{if(memoryMotion)v.play().catch(()=>{});else v.pause()})}});
document.addEventListener('visibilitychange',()=>{document.querySelectorAll('[data-memory-loop]').forEach(v=>{if(document.hidden)v.pause();else if(memoryMotion&&v.getBoundingClientRect().bottom>0&&v.getBoundingClientRect().top<innerHeight)v.play().catch(()=>{})})});
